# r10uvm154 — the GRID GENERATOR for grid 1 (12 enum bases x 11 value
# spellings, one package per cell).  grids 2-4 are generated by the same shape
# with different axis lists; see README §4.  MEASUREMENT ONLY.
#
#   python3 gengrid154.py            # writes /tmp/r10uvm154_probe/grid/*.sv
#   SLANG_UHDM=<bin> gridrun154.sh <src.sv> <workroot>   # one cell, golden + ours
#   python3 score154.py <pris-root> <pat-root>           # golden-scored verdicts
#
# `logic [7:0]` with a negative member is a genuine slang width error and comes
# back SLANG_REJECT; it is listed, not hidden.
import os
OUT = os.environ.get("GRIDOUT", "/tmp/r10uvm154_probe/grid")
os.system("rm -rf " + OUT); os.makedirs(OUT)
bases = {
  "none":   ("", None),
  "int":    ("int", None),
  "integer":("integer", None),
  "bit32":  ("bit [31:0]", None),
  "logic8": ("logic [7:0]", None),
  "byte":   ("byte", None),
  "shortint":("shortint", None),
  "longint":("longint", None),
  "uint":   ("int unsigned", None),
  "tdbit32":("bt32_t", "typedef bit [31:0] bt32_t;"),
  "tdint":  ("ti_t",   "typedef int ti_t;"),
  "logic32":("logic [31:0]", None),
}
spells = [
  ("m1",     "-1",            False),
  ("m2",     "-2",            False),
  ("h32full","32'hFFFF_FFFF", False),
  ("hufull", "'hFFFFFFFF",    False),
  ("parm1",  "-(1)",          False),
  ("sub",    "1-2",           False),
  ("nott",   "~0",            False),
  ("pref",   "PM1",           True),
  ("neg9",   "-9",            False),
  ("d7",     "7",             False),
  ("succ",   None,            False),   # E_A = -1, E_B implicit successor
]
n=0
for bt, (btxt, td) in bases.items():
    for st, stxt, needp in spells:
        name = "b_%s__v_%s" % (bt, st)
        L = ["package p_%s;" % name]
        if td: L.append("   " + td)
        if needp: L.append("   parameter int PM1 = -1;")
        L.append("   typedef enum %s{" % (btxt + " " if btxt else ""))
        if st == "succ":
            L.append("      E_A = -1,")
            L.append("      E_B")
        else:
            L.append("      E_A = %s," % stxt)
            L.append("      E_Z = 7")
        L.append("   } e_%s;" % name)
        L.append("endpackage")
        L.append("module top_%s; e_%s v; initial v = E_A; endmodule" % (name, name))
        open(os.path.join(OUT, name + ".sv"), "w").write("\n".join(L) + "\n")
        n+=1
print("wrote", n)
